#include "motion_bank.hpp"
#include "picosha2.h"
#include <bit>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
namespace {
namespace bk=mh4u::motion_bank;namespace mp=mh4u::motion_pending;namespace mr=mh4u::motion_request;namespace mb=mh4u::motion_binding;
using Bytes=std::vector<std::uint8_t>;std::size_t checks{};
void check(bool yes,const std::string& why){++checks;if(!yes)throw std::runtime_error(why);}
std::uint32_t word(const Bytes& b,std::size_t p,unsigned n=4){if(p>b.size()||n>b.size()-p)throw std::runtime_error("Fixture extent");std::uint32_t x=0;for(unsigned i=0;i<n;++i)x|=std::uint32_t(b[p+i])<<(i*8);return x;}
void put(Bytes& b,std::size_t p,std::uint32_t x,unsigned n=4){if(p>b.size()||n>b.size()-p)throw std::runtime_error("Write extent");for(unsigned i=0;i<n;++i)b[p+i]=static_cast<std::uint8_t>(x>>(i*8));}
void append(Bytes& b,std::uint64_t x,unsigned n=4){for(unsigned i=0;i<n;++i)b.push_back(static_cast<std::uint8_t>(x>>(i*8)));}
void channel(Bytes& b,const mb::Channel& c){append(b,c.track.has_value(),1);if(c.track){append(b,c.track->resource_identity,8);append(b,c.track->bank);append(b,c.track->slot);append(b,c.track->ordinal);}append(b,c.frame_bits);append(b,c.weight_bits);append(b,c.key_data.has_value(),1);if(c.key_data){append(b,c.key_data->resource_identity,8);append(b,c.key_data->byte_offset,8);}}
std::array<const float*,14> floats(const mr::Layer& l){return {&l.requested_frame,&l.offset,&l.interpolation,&l.remaining_interpolation,&l.weight,&l.frame,&l.previous_frame,&l.end_frame,&l.field58,&l.speed,&l.field60,&l.prepared_frame,&l.prepared_next_frame,&l.previous_step};}
Bytes facts(const mp::Layer& v){Bytes b;const auto& a=v.animation;const auto& l=a.layer;append(b,l.selector);append(b,l.flags);append(b,l.field08);append(b,l.attributes);for(auto f:floats(l))append(b,std::bit_cast<std::uint32_t>(*f));for(const auto& ref:l.bindings){append(b,ref.has_value(),1);if(ref){append(b,ref->resource_identity,8);append(b,ref->bank);append(b,ref->slot);append(b,ref->group);}}for(const auto& values:{l.masks,l.previous_masks})for(auto x:values)append(b,x);for(auto x:l.interpolation_curve_bits)append(b,x);for(const auto* values:{&a.prediction_rotation,&a.prediction_translation,&a.previous_rotation,&a.base_rotation,&a.previous_translation,&a.base_translation,&v.rotation_98,&v.translation_c8})for(auto x:*values)append(b,x);channel(b,a.tracks.translation);channel(b,a.tracks.rotation);append(b,a.tracks.joints.size(),8);for(const auto& j:a.tracks.joints){append(b,j.flags);for(const auto& c:j.channels)channel(b,c);}return b;}
Bytes bank_facts(const mr::Bank& bank){Bytes b;append(b,bank.index());if(const auto* r=std::get_if<mr::Resource>(&bank)){append(b,r->identity,8);append(b,r->slots.has_value(),1);if(r->slots){append(b,reinterpret_cast<std::uintptr_t>(r->slots->data()),8);append(b,r->slots->size(),8);}}return b;}
mr::Bank bank(std::uint32_t pointer){if(!pointer)return mr::Absent{};return mr::Resource{0x1234000000000000ULL|pointer,std::nullopt};}
std::uint32_t pointer(const mr::Bank& b){if(std::holds_alternative<mr::Absent>(b))return 0;if(const auto* r=std::get_if<mr::Resource>(&b))return static_cast<std::uint32_t>(r->identity);throw std::runtime_error("Unknown fixture bank");}
mp::Layer layer(const Bytes& b,std::size_t p){mp::Layer v{};auto& a=v.animation;auto& l=a.layer;l.selector=static_cast<std::uint16_t>(word(b,p+4,2));l.flags=static_cast<std::uint16_t>(word(b,p+6,2));l.field08=static_cast<std::uint16_t>(word(b,p+8,2));l.attributes=word(b,p+12);std::array<float*,14> fields{&l.requested_frame,&l.offset,&l.interpolation,&l.remaining_interpolation,&l.weight,&l.frame,&l.previous_frame,&l.end_frame,&l.field58,&l.speed,&l.field60,&l.prepared_frame,&l.prepared_next_frame,&l.previous_step};constexpr std::array<std::size_t,14> offsets{0x10,0x14,0x40,0x44,0x48,0x4c,0x50,0x54,0x58,0x5c,0x60,0x64,0x68,0x18};for(unsigned i=0;i<14;++i)*fields[i]=std::bit_cast<float>(word(b,p+offsets[i]));for(unsigned g=0;g<4;++g){l.bindings[g]=mr::Binding{0x1111000000000000ULL|word(b,p+0xf8+4*g),g+8,word(b,p+8+4*g),g};l.masks[g]=word(b,p+0x108+4*g);l.previous_masks[g]=word(b,p+0x118+4*g);}for(unsigned i=0;i<2;++i)l.interpolation_curve_bits[i]=word(b,p+0x6c+4*i);std::array<mh4u::motion_initialization::Bits4*,8> vectors{&a.prediction_rotation,&a.prediction_translation,&a.previous_rotation,&a.base_rotation,&a.previous_translation,&a.base_translation,&v.rotation_98,&v.translation_c8};constexpr std::array<std::size_t,8> vo{0x20,0x30,0x78,0x88,0xa8,0xb8,0x98,0xc8};for(unsigned i=0;i<8;++i)for(unsigned k=0;k<4;++k)(*vectors[i])[k]=word(b,p+vo[i]+4*k);auto ch=[&](std::size_t off){return mb::Channel{mb::TrackReference{0xabcd000000000000ULL|word(b,p+off),13,7,3},word(b,p+off+4),mb::BufferReference{0xdef0000000000000ULL|word(b,p+off),word(b,p+off+8)},word(b,p+off+12)};};a.tracks.translation=ch(0xd8);a.tracks.rotation=ch(0xe8);a.tracks.joints.push_back({{ch(0xd8),ch(0xe8),ch(0xd8)},word(b,p)});return v;}
void boundaries(){mr::Model m{};m.skeleton_present=true;std::vector<mp::Layer> layers(3);layers[0].animation.layer.selector=0xffff;layers[0].animation.layer.flags=0x101;layers[1].animation.layer.selector=0xf002;layers[1].animation.layer.flags=0xffff;layers[2]=layers[0];auto result=bk::replace(m,layers,2,15,mr::Absent{});check(std::holds_alternative<bk::Output>(result),"Known absent replacement");const auto& o=std::get<bk::Output>(result);check(o.layers[0].animation.layer.flags==2,"FFFF bank15 pending");check(o.layers[1].animation.layer.flags==0xffff,"Upper selector nibble ignored, bank0 preserved");check(o.layers[2].animation.layer.flags==0x101,"Inactive storage preserved");check(m.skeleton_present&&o.model.skeleton_present,"Skeleton copied");auto error=[&](bk::Result r,bk::ErrorCode e){check(std::holds_alternative<bk::Error>(r)&&std::get<bk::Error>(r).code==e,"Typed boundary error");};error(bk::replace(m,layers,2,16,mr::Absent{}),bk::ErrorCode::bank_extent);error(bk::replace(m,layers,4,0,mr::Absent{}),bk::ErrorCode::active_layer_extent);error(bk::replace(m,layers,2,0,mr::Unknown{}),bk::ErrorCode::unknown_replacement);error(bk::replace(m,layers,2,0,mr::Resource{0,{}}),bk::ErrorCode::resource_identity);error(bk::replace(m,layers,2,0,mr::Absent{},{2,256}),bk::ErrorCode::resource_limit);layers[2].animation.tracks.joints.resize(2);error(bk::replace(m,layers,2,0,mr::Absent{},{8,1}),bk::ErrorCode::resource_limit);check(layers[0].animation.layer.flags==0x101,"Errors publish no mutation");std::array<std::optional<mr::Action>,1> slots{};mr::Resource r{77,std::span<const std::optional<mr::Action>>(slots)};m.banks[0]=r;auto same=bk::replace(m,layers,2,0,r);check(std::get<bk::Output>(same).layers[1].animation.layer.flags==2,"Same identity still pending");check(bank_facts(std::get<bk::Output>(same).model.banks[0])==bank_facts(m.banks[0]),"Borrowed exact span preserved");check(std::holds_alternative<bk::Output>(bk::replace(m,{},0,0,mr::Absent{})),"Empty active/storage allowed");}
void oracle(const std::string& path,const std::string& expected){std::ifstream in(path,std::ios::binary);check(bool(in),"Fixture open");Bytes data((std::istreambuf_iterator<char>(in)),{});check(data.size()<=32U*1024U*1024U,"Fixture size limit");check(picosha2::hash256_hex_string(data)==expected,"Fixture SHA256");check(data.size()>=20&&std::string(data.begin(),data.begin()+8)=="MH4UBK01","Fixture version");check(word(data,8)==400&&word(data,12)==8192&&word(data,16)==512,"Fixture declared shape");std::size_t at=20,produced=0,unchanged=0,logical=0;for(unsigned ci=0;ci<400;++ci){const auto size=word(data,at);at+=4;check(size>=17432&&size<=20000&&size<=data.size()-at,"Case bounds");Bytes c(data.begin()+static_cast<std::ptrdiff_t>(at),data.begin()+static_cast<std::ptrdiff_t>(at+size));at+=size;const auto bi=word(c,4),active=word(c,8),replacement=word(c,16);check(word(c,0)==ci&&bi<16&&active<=8&&word(c,12)<5,"Case metadata");constexpr std::size_t input=20,output=20+8192+512;Bytes before(c.begin()+input,c.begin()+input+8192),after(c.begin()+output,c.begin()+output+8192);check(word(before,0x234)==active,"Active count agreement");std::vector<mp::Layer> ls;mr::Model m{};m.skeleton_present=ci%2;for(unsigned i=0;i<8;++i)ls.push_back(layer(before,0x240+304*i));for(unsigned i=0;i<16;++i)m.banks[i]=bank(word(before,0xc04+4*i));const auto pristine=ls;const auto model_before=m;const auto r=bk::replace(m,ls,active,bi,bank(replacement));check(std::holds_alternative<bk::Output>(r),"Numerical bank operation accepted");const auto& out=std::get<bk::Output>(r);check(out.layers.size()==8&&out.model.skeleton_present==m.skeleton_present,"Output storage/skeleton");Bytes projection=before;for(unsigned i=0;i<16;++i){const auto want=i==bi?bank(replacement):m.banks[i];check(bank_facts(out.model.banks[i])==bank_facts(want),"Exact resource identity/presence/span");check(bank_facts(m.banks[i])==bank_facts(model_before.banks[i]),"Input model immutable");put(projection,0xc04+4*i,pointer(out.model.banks[i]));}for(unsigned i=0;i<8;++i){auto expected_layer=pristine[i];expected_layer.animation.layer.flags=static_cast<std::uint16_t>(word(after,0x246+304*i,2));check(facts(out.layers[i])==facts(expected_layer),"All canonical fields preserved except ARM flag result");check(facts(ls[i])==facts(pristine[i]),"Input layer immutable");logical+=facts(out.layers[i]).size();put(projection,0x246+304*i,out.layers[i].animation.layer.flags,2);}check(projection==after,"Whole model projection matches original");produced+=16*4+8*2;unchanged+=8192-(16*4+8*2);const auto stores=word(c,output+8192+512);check(stores<=12&&c.size()==output+8192+512+4+16*stores,"Store trace extent");}check(at==data.size(),"No trailing fixture bytes");std::cout<<"BANK_ORACLE\tcases=400\tprojected_fields_bytes="<<produced<<"\tunchanged_opaque_bytes="<<unchanged<<"\tcanonical_fact_bytes="<<logical<<"\n";}
}
int main(int argc,char** argv){try{boundaries();if(argc==3)oracle(argv[1],argv[2]);else if(argc!=1)throw std::runtime_error("usage: motion_bank_tests [oracle.bin sha256]");std::cout<<"BANK_TESTS\tchecks="<<checks<<"\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
